initJs:
function(container, apiUrl, tables) {
  // 店舗データの初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 予測結果テーブルの描画
  function renderPredictionResults(results) {
    const tbody = container.querySelector('#prediction-tbody');
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">予測結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.予測結果ID || ''}">
        <td>${result.商品コード || '-'}</td>
        <td>${result.商品名 || '-'}</td>
        <td>${result.現在在庫 || 0}</td>
        <td>${result.予測数量 || 0}</td>
        <td>${result.推奨発注数量 || 0}</td>
        <td>${result.予測精度 || 0}%</td>
        <td>
          <button class="action-btn secondary" onclick="window.showScreen('scr-1778591896813')">発注量計算</button>
        </td>
      </tr>
    `).join('');
  }

  // グラフ描画関数
  function drawPredictionChart() {
    const canvas = container.querySelector('#prediction-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const dates = ['1/1', '1/2', '1/3', '1/4', '1/5', '1/6', '1/7'];
    const actualData = [120, 135, 98, 156, 142, 178, 165];
    const predictedData = [125, 140, 95, 160, 145, 175, 170];

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const maxValue = Math.max(...actualData, ...predictedData) * 1.1;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 実績データの描画
    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    actualData.forEach((value, index) => {
      const x = padding + (index * chartWidth) / (dates.length - 1);
      const y = canvas.height - padding - (value / maxValue) * chartHeight;
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 予測データの描画
    ctx.strokeStyle = '#ff6a00';
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    predictedData.forEach((value, index) => {
      const x = padding + (index * chartWidth) / (dates.length - 1);
      const y = canvas.height - padding - (value / maxValue) * chartHeight;
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();
    ctx.setLineDash([]);

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '14px sans-serif';
    ctx.fillText('実績値', padding + 20, padding - 20);
    ctx.fillText('予測値', padding + 100, padding - 20);

    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(padding, padding - 15);
    ctx.lineTo(padding + 15, padding - 15);
    ctx.stroke();

    ctx.strokeStyle = '#ff6a00';
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(padding + 80, padding - 15);
    ctx.lineTo(padding + 95, padding - 15);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  function drawComparisonChart() {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const categories = ['食品', '飲料', '日用品', '冷凍食品'];
    const actualValues = [85, 92, 78, 88];
    const predictedValues = [88, 89, 82, 85];

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const barWidth = chartWidth / (categories.length * 2 + 1);

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // バーの描画
    categories.forEach((category, index) => {
      const x = padding + (index * 2 + 1) * barWidth;

      // 実績バー
      const actualHeight = (actualValues[index] / 100) * chartHeight;
      ctx.fillStyle = '#4a9eff';
      ctx.fillRect(x, canvas.height - padding - actualHeight, barWidth * 0.8, actualHeight);

      // 予測バー
      const predictedHeight = (predictedValues[index] / 100) * chartHeight;
      ctx.fillStyle = '#ff6a00';
      ctx.fillRect(x + barWidth, canvas.height - padding - predictedHeight, barWidth * 0.8, predictedHeight);

      // カテゴリ名
      ctx.fillStyle = '#d0e4ff';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(category, x + barWidth, canvas.height - padding + 20);
    });
  }

  // バリデーション関数
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const model = container.querySelector('#model-select').value;

    if (!storeId) {
      return '店舗を選択してください';
    }
    if (!category) {
      return '商品カテゴリを選択してください';
    }
    if (!startDate) {
      return '予測期間の開始日を設定してください';
    }
    if (!endDate) {
      return '予測期間の終了日を設定してください';
    }
    if (!model) {
      return '予測モデルを選択してください';
    }

    const start = new Date(startDate);
    const end = new Date(endDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (start < today) {
      return '開始日は現在日以降の日付を設定してください';
    }
    if (start >= end) {
      return '開始日は終了日より前の日付を入力してください';
    }

    return null;
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 予測実行
  container.querySelector('#btn-predict').addEventListener('click', async () => {
    const error = validateForm();
    if (error) {
      showError(error);
      return;
    }

    const btn = container.querySelector('#btn-predict');
    const originalText = btn.textContent;
    btn.textContent = '予測実行中...';
    btn.disabled = true;

    try {
      // 予測結果データの作成
      const storeId = container.querySelector('#store-select').value;
      const category = container.querySelector('#category-select').value;
      const startDate = container.querySelector('#start-date').value;
      const endDate = container.querySelector('#end-date').value;

      // サンプル予測結果データ
      const sampleResults = [
        {
          予測結果ID: 'pred-001',
          商品コード: 'P001',
          商品名: 'おにぎり（鮭）',
          現在在庫: 45,
          予測数量: 120,
          推奨発注数量: 75,
          予測精度: 92
        },
        {
          予測結果ID: 'pred-002',
          商品コード: 'P002',
          商品名: 'サンドイッチ',
          現在在庫: 23,
          予測数量: 85,
          推奨発注数量: 62,
          予測精度: 88
        }
      ];

      // 予測精度指標の更新
      container.querySelector('#accuracy-value').textContent = '90.5%';
      container.querySelector('#confidence-value').textContent = '85.2%';
      container.querySelector('#period-value').textContent = `${startDate} ～ ${endDate}`;

      // 結果表示
      container.querySelector('#prediction-results').classList.remove('hidden');
      renderPredictionResults(sampleResults);
      drawPredictionChart();
      drawComparisonChart();

      // 結果をスクロール表示
      container.querySelector('#prediction-results').scrollIntoView({ behavior: 'smooth' });

    } catch (error) {
      showError('予測処理中にエラーが発生しました');
    } finally {
      btn.textContent = originalText;
      btn.disabled = false;
    }
  });

  // エクスポート機能
  container.querySelector('#btn-export').addEventListener('click', () => {
    const results = [
      ['商品コード', '商品名', '現在在庫', '予測需要量', '推奨発注量', '予測精度'],
      ['P001', 'おにぎり（鮭）', '45', '120', '75', '92%'],
      ['P002', 'サンドイッチ', '23', '85', '62', '88%']
    ];

    const csvContent = '\uFEFF' + results.map(row => 
      row.map(cell => `"${cell}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 再予測
  container.querySelector('#btn-refresh').addEventListener('click', () => {
    container.querySelector('#prediction-results').classList.add('hidden');
  });

  // 初期化
  initStoreOptions();

  // 初期日付設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const nextWeek = new Date(today);
  nextWeek.setDate(nextWeek.getDate() + 7);

  container.querySelector('#start-date').value = tomorrow.toISOString().split('T')[0];
  container.querySelector('#end-date').value = nextWeek.toISOString().split('T')[0];
}
